package e.e.a;import android.app.*;import android.content.*;public class CachePickerCancelTest{static void check(boolean b,String s){if(!b)throw new AssertionError(s);}public static void main(String[] args){Activity menu=new Activity();CacheFolders.Picker p=new CacheFolders.Picker();p.activity=menu;p.pending=new Intent(new ComponentName("com.sauzask.nicoid.NicoidCacheManagerActivity"));p.picking=true;p.onActivityResult(41,Activity.RESULT_CANCELED,null);check(menu.finishes==0,"Cancelling from menu must keep original screen");check(p.pending==null&&!p.picking,"Cancelled navigation clears pending request");Activity blank=new Activity();p.activity=blank;p.pending=new Intent(new ComponentName("com.sauzask.nicoid.NicoidCacheManagerActivity")).putExtra("nicoid_cache_replace_picker_host",true);p.onActivityResult(41,Activity.RESULT_CANCELED,null);check(blank.finishes==1,"Cancel direct-entry blank host safely");p.activity=menu;p.pending=new Intent(new ComponentName("com.sauzask.nicoid.NicoidDownloadCache"));p.onActivityResult(41,Activity.RESULT_CANCELED,null);check(menu.finishes==0,"Cancelled download keeps originating screen");System.out.println("Folder-picker cancellation: 4 menu/direct/download lifecycle checks passed");}}
